+
 void opencl_process_event(void)
 {
+	if (!bench_running) {
 #if !OS_TIMER
-	sig_timer_emu_tick();
+		sig_timer_emu_tick();
 #endif
-	if (event_pending) {
-		if (event_save) {
-			event_save = 0;
-			rec_save();
-		}
+		if (event_pending) {

-		if (event_status) {
-			event_status = 0;
-			status_print();
-		}
